void delete_from_list(struct node **list, int n) {
	// make list point to pointer to node before node with n
	while ((*list)->next->value != n) {
		list = &((*list)->next);
		// next iteration would cause SF (otherwise, n wasnt found)
		if ((*list)->next == NULL)
