func Decode(path string, t Type) (image.Image, error) {
	fp, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer fp.Close()

	br := bufio.NewReader(fp)

	var im image.Image
	var imgerr error
	switch t {
	case TypeJpeg: // JPEG
		im, imgerr = jpeg.Decode(br)
	case TypePng: // PNG
		im, imgerr = png.Decode(br)
	case TypeGif: // GIF
		im, imgerr = gif.Decode(br)
	case TypeTiff: // TIFF
		im, imgerr = tiff.Decode(br)
	case TypeWebp: // WEBP
		im, imgerr = webp.Decode(br)
	case TypeBmp: // BMP
		im, imgerr = bmp.Decode(br)
	default:
		imgerr = errors.New("unknown image type")
	}
	if imgerr != nil {
		return nil, imgerr
	}
	return im, nil
}

